 if(step===9){engineer.prompt='Protect life-support power during the surface problem.';engineer.choices=[{label:'Keep life support first; shut down optional tools',power:5,air:2,food:0,note:'Essential systems stay powered.'},{label:'Keep every instrument running',power:-9,air:-4,food:0,note:'The crew loses energy and life-support margin.'}];scientist.title='PLAYER 2 · SAFETY SCIENTIST';scientist.prompt='Secure the sample and choose a safe response.';scientist.choices=[{label:'Seal the sample and shelter until conditions are checked',power:-1,air:4,food:0,note:'Sample secured; crew shelter and check conditions.'},{label:'Continue outside and leave the sample open',power:-2,air:-6,food:0,note:'Exposure and contamination risks increase.'}];}
