function reachSite(){if(driveReached||solved)return;driveReached=true;teamJobsDone.engineer=true;$('#drive-pad').hidden=true;$('#mission-panel').classList.remove('driving');velocity=0;keys.clear();$('#next').hidden=true;setFeedback(level==='beginner'?'You reached the green light! The Engineer is parked; Player 2 should finish the route check.':'Beacon reached. Player 1 parked the rover; Player 2 must complete the navigation check.',false);const arrival=document.querySelector('#collect-at-site');if(arrival)arrival.disabled=true;updateStageCompletion();}function complete(){keys.clear();$('#drive-pad').hidden=true;$('#chapter').textContent=level==='beginner'?'MISSION FINISHED':'EXPEDITION COMPLETE';$('#progress-bar').style.width='100%';$('#objective').textContent=level==='beginner'?'Great work, explorer!':'You made science happen.';$('#brief').textContent=level==='beginner'?`Your crew finished its ${regionName()} trip on ${world}. Think about one choice that helped and one thing you would try next time.`:`Your ${world} team completed the ${regionName()} expedition. Explain one supply trade-off, one piece of evidence, and one question you would investigate next.`;$('#mentor').textContent='MISSION COACH · TEAM REVIEW';$('#actions').replaceChildren();const b=document.createElement('button');b.className='action primary';b.textContent='Choose another site ↻';b.addEventListener('click',reset);$('#actions').append(b);setFeedback(level==='beginner'?`Supplies left — power ${Math.round(battery)}, water / air ${Math.round(air)}, food ${Math.round(shield)} teaching units. Sample: ${sampleQuality}. Message: ${linked?'sent':'not sent'}.`:`Final reserves — power ${Math.round(battery)} · water / air ${Math.round(air)} · food ${Math.round(shield)} teaching units. Sample: ${sampleQuality}. Report: ${linked?'sent through relay':'not sent'}.`,false);try{const value=JSON.parse(localStorage.getItem('junior-astronaut-trainer-progress')||'{}');value[`${level}-${world}-${region}`]=true;localStorage.setItem('junior-astronaut-trainer-progress',JSON.stringify(value));}catch{}controls.target.set(0,1,0);camera.position.set(30,23,34);controls.update();updateTelemetry();}
function start(destination,selectedRegion){world=destination;region=selectedRegion|| (world==='Moon'?'shackleton':'jezero');step=0;battery=level==='beginner'?95:76;air=level==='beginner'?90:68;shield=level==='beginner'?93:72;sample=false;sampleQuality='—';linked=false;missionLog=[];selectedSite='not selected';greenhousePlan='not selected';transitionNote='';cropChoice=-1;cropBlocks=0;cropHarvested=0;$('#welcome').hidden=true;$('#mission-panel').hidden=false;$('#location').textContent=world.toUpperCase()+' · '+regionName().toUpperCase()+' · ORBITAL APPROACH';buildOrbit();updateTelemetry();renderStage();}
